const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

if ((canId & 0x1FFFF000) !== 0x14F00000) {
    return null;
}

const msgType = (canId >> 8) & 0x0F;
const bmsAddr = canId & 0xFF;

var hexStr = "";
for (var i = 0; i < data.length; i++) {
    hexStr += ("0" + data[i].toString(16).toUpperCase()).slice(-2) + " ";
}

var msgNames = {
    1: "Status (Current/Voltage/Capacity)",
    2: "Cells (Max/Min/Avg Voltage, Temp)",
    3: "Capacity (Rated/TotalWh/Cycles)",
    4: "Info (FW Version/SOH)",
    5: "Serial Part 1",
    6: "Serial Part 2",
    7: "Serial Part 3"
};

msg.payload = {
    canIdHex: "0x" + canId.toString(16).toUpperCase(),
    msgType: msgType,
    msgName: msgNames[msgType] || "Unknown",
    bmsAddress: bmsAddr,
    rawHex: hexStr.trim(),
    rawBytes: Array.from(data),
    byte0: data[0],
    byte1: data[1],
    byte2: data[2],
    byte3: data[3],
    byte4: data[4],
    byte5: data[5],
    byte6: data[6],
    byte7: data[7],
    uint16_0_1: (data[0] & 0xFF) | ((data[1] & 0xFF) << 8),
    uint16_2_3: (data[2] & 0xFF) | ((data[3] & 0xFF) << 8),
    uint16_4_5: (data[4] & 0xFF) | ((data[5] & 0xFF) << 8),
    uint16_6_7: (data[6] & 0xFF) | ((data[7] & 0xFF) << 8)
};

return msg;
